cd <run-dir>; sqlite3 -header warehouse.db "
select g.region, round(sum(p.premium_amt - p.cancellation_amt),2) nwp, round(sum(p.premium_amt),2) nwp_before_canc, round(sum(case when p.status='written' then p.premium_amt end),2) written_only
 from fct_policy_premium p join dim_geography g on g.geo_id=p.geo_id where p.status in ('written','cancelled') and p.eff_dt between '2026-07-01' and '2026-09-30' group by g.region;
select d.product_line, round(sum(p.premium_amt_gross),2) gwp from fct_policy_premium p join dim_product d on d.product_id=p.product_id where p.status in ('written','cancelled') and p.eff_dt between '2026-01-01' and '2026-06-30' group by d.product_line;
select status, count(*) from fct_policy_premium where eff_dt between '2026-03-01' and '2026-03-31' group by status;
select severity, round(sum(paid_amt),2), count(*) from fct_claims where status='closed' and closed_dt between '2026-04-01' and '2026-06-30' group by severity;
select g.region, round(sum(c.claim_amt),2) incurred, round(sum(c.paid_amt),2) paid from fct_claims c join fct_policy_premium p on p.policy_id=c.policy_id join dim_geography g on g.geo_id=p.geo_id where c.reported_dt between '2026-07-01' and '2026-09-30' group by g.region;"

